Scripts.OnEnter:
SimpleTooltip_SetOwner(this);
GameTooltip:SetText("AtlasLoot");
GameTooltip:AddLine("|cffffd100Click to open or close Atlas.|r");
GameTooltip:Show();

Scripts.OnLoad:
this:SetFrameLevel(this:GetFrameLevel() + 2);
if ( this:GetID() == 0 ) then
	this.unit = "player";
else
	this.unit = "party"..this:GetID();
end
getglobal(this:GetName().."Icon"):SetVertexColor(1.0, 1.0, 1.0);

